    assertThat("Expect rewrite to contain the correct path.", outputUrl.toString(), is("mock-scheme://output-mock-host-3:42/no-query"));
    outputUrl = processor.rewrite(null, inputUrl, UrlRewriter.Direction.OUT, "test-rule-4");
    assertThat("Expect rewrite to contain the correct path.", outputUrl.toString(), is("mock-scheme://output-mock-host-4:42/no-query"));
    processor.destroy();
}

