    The client receives a HttpStatus.SC_CREATED Created respond with zero content length and the WebHDFS URI of the file in the Location header:
    HTTP/1.1 HttpStatus.SC_CREATED Created
    Location: webhdfs://<HOST>:<PORT>/<PATH>
    Content-Length: 0
    */
    driver.getMock("WEBHDFS").expect().method("PUT").pathInfo("/v1" + root + "/dir/file").queryParam("op", "CREATE").queryParam("user.name", username).respond().status(HttpStatus.SC_TEMPORARY_REDIRECT).header("Location", driver.getRealUrl("DATANODE") + "/v1" + root + "/dir/file?op=CREATE&user.name=hdfs");
    driver.getMock("DATANODE").expect().method("PUT").pathInfo("/v1" + root + "/dir/file").queryParam("op", "CREATE").queryParam("user.name", username).contentType("text/plain").content(driver.getResourceBytes("test.txt")).//.content( driver.gerResourceBytes( "hadoop-examples.jar" ) )
    respond().status(HttpStatus.SC_CREATED).header("Location", "webhdfs://" + driver.getRealAddr("DATANODE") + "/v1" + root + "/dir/file");
    Response response = given().//.log().all()
    auth().preemptive().basic(username, password).header("X-XSRF-Header", "jksdhfkhdsf").queryParam("op", "CREATE").expect().//.log().ifError()
    statusCode(HttpStatus.SC_TEMPORARY_REDIRECT).when().put(driver.getUrl("WEBHDFS") + "/v1" + root + "/dir/file");
    String location = response.getHeader("Location");
    log.debug("Redirect location: " + response.getHeader("Location"));
    if (driver.isUseGateway()) {
        MatcherAssert.assertThat(location, anyOf(startsWith("http://" + gatewayHostName + ":" + gatewayAddress.getPort() + "/"), startsWith("http://" + gatewayAddrName + ":" + gatewayAddress.getPort() + "/")));
        MatcherAssert.assertThat(location, containsString("?_="));
    }
    MatcherAssert.assertThat(location, not(containsString("host=")));
    MatcherAssert.assertThat(location, not(containsString("port=")));
    response = given().//.log().all()
    auth().preemptive().basic(username, password).header("X-XSRF-Header", "jksdhfkhdsf").content(driver.getResourceBytes("test.txt")).contentType("text/plain").expect().//.log().ifError()
    statusCode(HttpStatus.SC_CREATED).when().put(location);
    location = response.getHeader("Location");
    log.debug("Created location: " + location);
    if (driver.isUseGateway()) {
        MatcherAssert.assertThat(location, anyOf(startsWith("http://" + gatewayHostName + ":" + gatewayAddress.getPort() + "/"), startsWith("http://" + gatewayAddrName + ":" + gatewayAddress.getPort() + "/")));
    }
    driver.assertComplete();
    /* Get the file.
    curl -i -L "http://<HOST>:<PORT>/webhdfs/v1/<PATH>?op=OPEN
                       [&offset=<LONG>][&length=<LONG>][&buffersize=<INT>]"

    The expect is redirected to a datanode where the file data can be read:
    HTTP/1.1 307 TEMPORARY_REDIRECT
    Location: http://<DATANODE>:<PORT>/webhdfs/v1/<PATH>?op=OPEN...
    Content-Length: 0

    The client follows the redirect to the datanode and receives the file data:
    HTTP/1.1 HttpStatus.SC_OK OK
    Content-Type: application/octet-stream
    Content-Length: 22

    Hello, webhdfs user!
    */
    driver.getMock("WEBHDFS").expect().method("GET").pathInfo("/v1" + root + "/dir/file").queryParam("op", "OPEN").queryParam("user.name", username).respond().status(HttpStatus.SC_TEMPORARY_REDIRECT).header("Location", driver.getRealUrl("DATANODE") + "/v1" + root + "/dir/file?op=OPEN&user.name=hdfs");
    driver.getMock("DATANODE").expect().method("GET").pathInfo("/v1" + root + "/dir/file").queryParam("op", "OPEN").queryParam("user.name", username).respond().status(HttpStatus.SC_OK).contentType("text/plain").content(driver.getResourceBytes("test.txt"));
    given().//.log().all()
    auth().preemptive().basic(username, password).header("X-XSRF-Header", "jksdhfkhdsf").queryParam("op", "OPEN").expect().//.log().ifError()
    statusCode(HttpStatus.SC_OK).content(is("TEST")).when().get(driver.getUrl("WEBHDFS") + "/v1" + root + "/dir/file");
    driver.assertComplete();
    /* Delete the directory.
    curl -i -X DELETE "http://<host>:<port>/webhdfs/v1/<path>?op=DELETE
                                 [&recursive=<true|false>]"

    The client receives a respond with a boolean JSON object:
    HTTP/1.1 HttpStatus.SC_OK OK
    Content-Type: application/json
    Transfer-Encoding: chunked

    {"boolean": true}
    */
    // Mock the interaction with the namenode.
    driver.getMock("WEBHDFS").expect().from("testBasicHdfsUseCase-1").method("DELETE").pathInfo("/v1" + root).queryParam("op", "DELETE").queryParam("user.name", username).queryParam("recursive", "true").respond().status(HttpStatus.SC_OK);
    given().auth().preemptive().basic(username, password).header("X-XSRF-Header", "jksdhfkhdsf").queryParam("op", "DELETE").queryParam("recursive", "true").expect().//.log().ifError()
    statusCode(HttpStatus.SC_OK).when().delete(driver.getUrl("WEBHDFS") + "/v1" + root);
    driver.assertComplete();
    LOG_EXIT();
}

