    outContent.reset();
    cli = new KnoxCLI();
    cli.setConf(config);
    username = "guest";
    password = "guest-password";
    String[] args4 = { "user-auth-test", "--master", "knox", "--cluster", "cluster-dne", "--u", username, "--p", password };
    cli.run(args4);
    assertThat(outContent.toString(), containsString("Topology cluster-dne does not exist"));
