    outContent.reset();
    cli = new KnoxCLI();
    cli.setConf(config);
    username = "guest";
    password = "guest-password";
    String[] args5 = { "user-auth-test", "--master", "knox", "--cluster", "test-cluster", "--u", username, "--p", password };
    cli.run(args5);
    assertThat(outContent.toString(), containsString("LDAP authentication success"));
    assertThat(outContent.toString(), not(containsString("does not belong to any groups")));
    LOG_EXIT();
}

